"""General utility functions for FoodomicsPy.This module contains helper functions for sorting sample IDs,aligning analytical data with metadata, cropping spectral regions,and comparing sample identifiers."""import reimport warningsimport numpy as npimport pandas as pd# =============================================================================# SAMPLE SORTING# =============================================================================def sort_sample_id_abc(df: pd.DataFrame) -> pd.DataFrame:    """    Sort a DataFrame by structured sample IDs.    Sample IDs are sorted according to:    1. Alphabetical prefix    2. Numerical sample number    3. Replicate label    Parameters    ----------    df : pandas.DataFrame        DataFrame containing sample IDs in its index.    Returns    -------    pandas.DataFrame        A copy of the DataFrame sorted by sample ID.    Raises    ------    TypeError        If `df` is not a pandas DataFrame.    ValueError        If a sample ID does not follow the expected format.    Examples    --------    Supported sample-ID formats include:    - ``1_a``    - ``10_b``    - ``C01_a``    - ``M19_c``    >>> sorted_df = sort_sample_id_abc(df)    """    if not isinstance(df, pd.DataFrame):        raise TypeError("df must be a pandas DataFrame.")    def sorting_key(sample_id: object) -> tuple[str, int, str]:        sample_id = str(sample_id)        match = re.fullmatch(            r"([A-Za-z]*)(\d+)_([A-Za-z]+)",            sample_id,        )        if match is None:            raise ValueError(                f"Invalid sample ID: '{sample_id}'. "                "Expected formats such as '1_a', 'C19_a', or 'M01_b'."            )        prefix, number, replicate = match.groups()        return (            prefix.lower(),            int(number),            replicate.lower(),        )    sorted_index = sorted(df.index, key=sorting_key)    return df.loc[sorted_index].copy()# =============================================================================# DATA AND METADATA ALIGNMENT# =============================================================================def align_data_metadata(    df: pd.DataFrame,    df_meta: pd.DataFrame,) -> tuple[pd.DataFrame, pd.DataFrame]:    """    Align analytical data and metadata using their sample indices.    Only samples present in both DataFrames are retained. The returned    DataFrames have the same samples in the same order.    Parameters    ----------    df : pandas.DataFrame        Analytical data with samples in rows and variables in columns.    df_meta : pandas.DataFrame        Metadata with samples in rows and metadata variables in columns.    Returns    -------    df_aligned : pandas.DataFrame        Data matrix containing samples found in both inputs.    df_meta_aligned : pandas.DataFrame        Metadata containing the same samples and sample order as        `df_aligned`.    Warns    -----    UserWarning        If samples occur in only one of the two DataFrames.    Raises    ------    TypeError        If either input is not a pandas DataFrame.    ValueError        If the DataFrames have duplicate sample IDs or no common samples.    Examples    --------    >>> df, df_meta = align_data_metadata(df, df_meta)    """    if not isinstance(df, pd.DataFrame):        raise TypeError("df must be a pandas DataFrame.")    if not isinstance(df_meta, pd.DataFrame):        raise TypeError("df_meta must be a pandas DataFrame.")    if not df.index.is_unique:        raise ValueError("df contains duplicate sample IDs.")    if not df_meta.index.is_unique:        raise ValueError("df_meta contains duplicate sample IDs.")    missing_metadata = df.index.difference(df_meta.index)    missing_data = df_meta.index.difference(df.index)    if len(missing_metadata) > 0:        warnings.warn(            f"{len(missing_metadata)} samples have data but no metadata: "            f"{missing_metadata.tolist()}",            UserWarning,            stacklevel=2,        )    if len(missing_data) > 0:        warnings.warn(            f"{len(missing_data)} samples have metadata but no data: "            f"{missing_data.tolist()}",            UserWarning,            stacklevel=2,        )    # Preserve the sample order from df    common_samples = df.index[df.index.isin(df_meta.index)]    if len(common_samples) == 0:        raise ValueError(            "No common sample IDs were found between df and df_meta."        )    df_aligned = df.loc[common_samples].copy()    df_meta_aligned = df_meta.loc[common_samples].copy()    return df_aligned, df_meta_aligned# =============================================================================# SPECTRAL CROPPING# =============================================================================def crop_spectra(    df: pd.DataFrame,    *regions: tuple[float, float],) -> pd.DataFrame:    """    Retain columns located within one or more spectral regions.    Parameters    ----------    df : pandas.DataFrame        Spectral data with samples in rows and spectral-axis values        in columns.    *regions : tuple of float        One or more spectral regions specified as ``(start, end)``.        Both increasing and decreasing ranges are accepted.    Returns    -------    pandas.DataFrame        A copy of the spectral data containing only the selected        spectral regions.    Raises    ------    TypeError        If `df` is not a pandas DataFrame or its columns cannot be        converted to numeric spectral-axis values.    ValueError        If no region is provided, a region does not contain exactly        two values, or no columns occur within the selected regions.    Notes    -----    The original spectral-axis order is preserved. The function does    not sort or otherwise modify the spectral axis.    Examples    --------    Retain one NMR region:    >>> df_cropped = crop_spectra(df, (10, 0))    Retain two FTIR regions:    >>> df_cropped = crop_spectra(    ...     df,    ...     (3050, 2800),    ...     (1800, 600),    ... )    """    if not isinstance(df, pd.DataFrame):        raise TypeError("df must be a pandas DataFrame.")    if len(regions) == 0:        raise ValueError(            "Provide at least one region, for example (10, 0)."        )    try:        axis_values = df.columns.astype(float).to_numpy()    except (TypeError, ValueError) as exc:        raise TypeError(            "The DataFrame columns must contain numeric spectral-axis values."        ) from exc    mask = np.zeros(len(axis_values), dtype=bool)    for region in regions:        if len(region) != 2:            raise ValueError(                "Each spectral region must contain exactly two values."            )        low, high = sorted(region)        mask |= (axis_values >= low) & (axis_values <= high)    if not mask.any():        raise ValueError(            "No spectral columns were found within the selected regions."        )    return df.loc[:, mask].copy()# =============================================================================# SAMPLE-ID COMPARISON# =============================================================================def compare_sample_ids(    df1: pd.DataFrame,    df2: pd.DataFrame,) -> dict[str, list]:    """    Compare sample IDs between two DataFrames.    Parameters    ----------    df1 : pandas.DataFrame        First DataFrame with sample IDs in its index.    df2 : pandas.DataFrame        Second DataFrame with sample IDs in its index.    Returns    -------    dict        Dictionary containing:        - ``only_in_df1``: sample IDs found only in `df1`        - ``only_in_df2``: sample IDs found only in `df2`    Raises    ------    TypeError        If either input is not a pandas DataFrame.    Examples    --------    >>> differences = compare_sample_ids(df1, df2)    >>> differences["only_in_df1"]    ['sample_1']    """    if not isinstance(df1, pd.DataFrame):        raise TypeError("df1 must be a pandas DataFrame.")    if not isinstance(df2, pd.DataFrame):        raise TypeError("df2 must be a pandas DataFrame.")    return {        "only_in_df1": df1.index.difference(df2.index).tolist(),        "only_in_df2": df2.index.difference(df1.index).tolist(),    }